         */
        public FeignLoggingRequestWrapper(HttpServletRequest request, byte[] bytes) {
            super(request);
            this.bytes = bytes;
        }

        @Override
        public ServletInputStream getInputStream() {
            return new ResettableServletInputStreamWrapper(bytes);
        }

        @Override
        public BufferedReader getReader() throws IOException {
            return new BufferedReader(new InputStreamReader(getInputStream(), super.getCharacterEncoding()));
        }
    }
}

