package com.everhomes.core;

import com.everhomes.core.scheduler.MonitorJobListener;
import com.everhomes.core.scheduler.SchedulerThreadPoolExecutorWithLog;
import org.quartz.spi.JobFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.SchedulingConfigurer;
import org.springframework.scheduling.concurrent.CustomizableThreadFactory;
import org.springframework.scheduling.config.ScheduledTaskRegistrar;
import org.springframework.scheduling.quartz.SchedulerFactoryBean;

import java.util.concurrent.ScheduledThreadPoolExecutor;

@Configuration
public class SchedulerConfig implements SchedulingConfigurer {

    @Value("${scheduler.pool.size}")
    private int poolSize;
    
    @Override
    public void configureTasks(ScheduledTaskRegistrar taskRegistrar) {
        taskRegistrar.setScheduler(taskExecutor());
    }

    @Bean(destroyMethod="shutdown")
    public ScheduledThreadPoolExecutor taskExecutor() {
        return new SchedulerThreadPoolExecutorWithLog(poolSize, new CustomizableThreadFactory("schedule-"));
    }

    @Bean
    @ConditionalOnMissingBean
    public SchedulerFactoryBean schedulerFactoryBean(JobFactory jobFactory){
        SchedulerFactoryBean bean = new SchedulerFactoryBean();
        bean.setApplicationContextSchedulerContextKey("applicationContext");
        bean.setAutoStartup(true);
        bean.setJobFactory(jobFactory);
        bean.setGlobalJobListeners(new MonitorJobListener());
        return bean;
    }
}

